import { FormLabel } from "@/components/ui/form";
import { cn } from "@/lib/utils";

function AutoFormLabel({
  label,
  isRequired,
  className,
}: {
  label: string;
  isRequired: boolean;
  className?: string;
}) {
  return (
    <>
      <FormLabel className={cn(className)}>
        {label}
        {isRequired && <span className="text-destructive"> *</span>}
      </FormLabel>
    </>
  );
}

export default AutoFormLabel;

function AutoFormTooltip({ fieldConfigItem }: { fieldConfigItem: any }) {
  return (
    <>
      {fieldConfigItem?.description && (
        <p className="text-sm text-gray-500 dark:text-white">
          {fieldConfigItem.description}
        </p>
      )}
    </>
  );
}

export default AutoFormTooltip;

import AutoFormFile from "./fields/file";
import AutoFormCheckbox from "./fields/checkbox";
import AutoFormDate from "./fields/date";
import AutoFormEnum from "./fields/enum";
import AutoFormInput from "./fields/input";
import AutoFormNumber from "./fields/number";
import AutoFormRadioGroup from "./fields/radio-group";
import AutoFormSwitch from "./fields/switch";
import AutoFormTextarea from "./fields/textarea";

export const INPUT_COMPONENTS = {
  file: AutoFormFile,
  checkbox: AutoFormCheckbox,
  date: AutoFormDate,
  select: AutoFormEnum,
  radio: AutoFormRadioGroup,
  switch: AutoFormSwitch,
  textarea: AutoFormTextarea,
  number: AutoFormNumber,
  fallback: AutoFormInput,
};

/**
 * Define handlers for specific Zod types.
 * You can expand this object to support more types.
 * 
 * Supports both:
 * - Zod v3 style: "ZodBoolean", "ZodEnum", etc. (from _def.typeName)
 * - Zod v4 style: "boolean", "enum", etc. (from _def.type)
 */
export const DEFAULT_ZOD_HANDLERS: {
  [key: string]: keyof typeof INPUT_COMPONENTS;
} = {
  // Zod v3 style type names
  ZodBoolean: "checkbox",
  ZodDate: "date",
  ZodEnum: "select",
  ZodNativeEnum: "select",
  ZodNumber: "number",
  // Zod v4 style type names (lowercase, no "Zod" prefix)
  boolean: "checkbox",
  date: "date",
  enum: "select",
  nativeEnum: "select",
  number: "number",
  int: "number",
  float: "number",
};

import type { FieldValues, UseFormWatch } from "react-hook-form";
import type { Dependency, EnumValues } from "./types";
import { DependencyType } from "./types";
import * as z from "zod";

export default function resolveDependencies<
  SchemaType extends z.infer<z.ZodObject<any, any>>,
>(
  dependencies: Dependency<SchemaType>[],
  currentFieldName: keyof SchemaType,
  watch: UseFormWatch<FieldValues>,
) {
  let isDisabled = false;
  let isHidden = false;
  let isRequired = false;
  let overrideOptions: EnumValues | undefined;

  const currentFieldValue = watch(currentFieldName as string);

  const currentFieldDependencies = dependencies.filter(
    (dependency) => dependency.targetField === currentFieldName,
  );
  for (const dependency of currentFieldDependencies) {
    const watchedValue = watch(dependency.sourceField as string);

    const conditionMet = dependency.when(watchedValue, currentFieldValue);

    switch (dependency.type) {
      case DependencyType.DISABLES:
        if (conditionMet) {
          isDisabled = true;
        }
        break;
      case DependencyType.REQUIRES:
        if (conditionMet) {
          isRequired = true;
        }
        break;
      case DependencyType.HIDES:
        if (conditionMet) {
          isHidden = true;
        }
        break;
      case DependencyType.SETS_OPTIONS:
        if (conditionMet) {
          overrideOptions = dependency.options;
        }
        break;
    }
  }

  return {
    isDisabled,
    isHidden,
    isRequired,
    overrideOptions,
  };
}

import {
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { Plus, Trash } from "lucide-react";
import { useFieldArray, useForm, useWatch } from "react-hook-form";
import * as z from "zod";
import { beautifyObjectName, getBaseSchema, getBaseType } from "../helpers";
import AutoFormObject from "./object";

function getDefType(schema: z.ZodType): string {
  return (schema as any)._zod?.def?.type || "";
}

function getArrayElementType(item: z.ZodType): z.ZodType | null {
  const def = (item as any)._zod?.def;
  const defType = getDefType(item);

  if (defType === "array") {
    return def?.element || null;
  }

  if (["default", "optional", "nullable"].includes(defType)) {
    const innerType = def?.innerType;
    if (innerType) {
      return getArrayElementType(innerType);
    }
  }

  return null;
}

function getPrimitiveDefault(itemSchema: z.ZodType): unknown {
  const base = getBaseSchema(itemSchema as z.ZodType);
  if (!base) return "";
  switch (getBaseType(base)) {
    case "ZodBoolean":
      return false;
    case "ZodNumber":
      return 0;
    default:
      return "";
  }
}

export default function AutoFormArray({
  name,
  item,
  form,
  path = [],
  fieldConfig,
}: {
  name: string;
  item: z.ZodArray<any> | z.ZodDefault<any>;
  form: ReturnType<typeof useForm>;
  path?: string[];
  fieldConfig?: any;
}) {
  const itemDefType = getArrayElementType(item);
  const elementBaseSchema = itemDefType
    ? getBaseSchema(itemDefType as z.ZodType)
    : null;
  const elementPrimitiveType = elementBaseSchema
    ? getBaseType(elementBaseSchema as z.ZodType)
    : "";
  const isObjectArray = !!itemDefType && elementPrimitiveType === "ZodObject";

  const title = fieldConfig?.label ?? beautifyObjectName(name);

  if (isObjectArray) {
    return (
      <ObjectAutoFormArray
        name={name}
        item={item}
        form={form}
        path={path}
        fieldConfig={fieldConfig}
        itemDefType={itemDefType as z.ZodObject<any, any>}
        title={title}
      />
    );
  }

  return (
    <PrimitiveAutoFormArray
      name={name}
      item={item}
      form={form}
      path={path}
      fieldConfig={fieldConfig}
      itemDefType={itemDefType}
      title={title}
    />
  );
}

/**
 * ObjectAutoFormArray — uses useFieldArray (safe for object arrays because
 * react-hook-form only wraps objects; the `id` field it injects doesn't affect
 * validation since the schema doesn't include it).
 */
function ObjectAutoFormArray({
  name,
  form,
  path = [],
  fieldConfig,
  itemDefType,
  title,
}: {
  name: string;
  item: z.ZodArray<any> | z.ZodDefault<any>;
  form: ReturnType<typeof useForm>;
  path?: string[];
  fieldConfig?: any;
  itemDefType: z.ZodObject<any, any>;
  title: string;
}) {
  const fieldPath = path.join(".");
  const { fields, append, remove } = useFieldArray({
    control: form.control,
    name: fieldPath,
  });

  return (
    <AccordionItem value={name} className="border-none">
      <AccordionTrigger>{title}</AccordionTrigger>
      <AccordionContent>
        {fields.map((_field, index) => {
          const key = _field.id;
          return (
            <div className="mt-4 flex flex-col" key={key}>
              <AutoFormObject
                schema={itemDefType}
                form={form}
                fieldConfig={fieldConfig}
                path={[...path, index.toString()]}
              />
              <div className="my-4 flex justify-end">
                <Button
                  variant="secondary"
                  size="icon"
                  type="button"
                  className="hover:bg-zinc-300 hover:text-black focus:ring-0 focus:ring-offset-0 focus-visible:ring-0 focus-visible:ring-offset-0 dark:bg-white dark:text-black dark:hover:bg-zinc-300 dark:hover:text-black dark:hover:ring-0 dark:hover:ring-offset-0 dark:focus-visible:ring-0 dark:focus-visible:ring-offset-0"
                  onClick={() => remove(index)}
                >
                  <Trash className="size-4" />
                </Button>
              </div>
              <Separator />
            </div>
          );
        })}
        <Button
          type="button"
          variant="secondary"
          onClick={() => append({})}
          className="mt-4 flex items-center"
        >
          <Plus className="mr-2" size={16} />
          Add
        </Button>
      </AccordionContent>
    </AccordionItem>
  );
}

/**
 * PrimitiveAutoFormArray — does NOT use useFieldArray.
 *
 * useFieldArray wraps every element in an object `{ id: "...", <value> }` which
 * corrupts primitive arrays (string[], number[], boolean[]). Instead we use
 * useWatch to observe the raw array and form.setValue to mutate it, keeping
 * the values as plain primitives that will pass Zod validation on submit.
 */
function PrimitiveAutoFormArray({
  name,
  item,
  form,
  path = [],
  fieldConfig,
  itemDefType,
  title,
}: {
  name: string;
  item: z.ZodArray<any> | z.ZodDefault<any>;
  form: ReturnType<typeof useForm>;
  path?: string[];
  fieldConfig?: any;
  itemDefType: z.ZodType | null;
  title: string;
}) {
  const fieldPath = path.join(".");
  const rawValues: unknown[] = useWatch({ control: form.control, name: fieldPath }) ?? [];
  const values = Array.isArray(rawValues) ? rawValues : [];

  const appendItem = () => {
    const def = itemDefType ? getPrimitiveDefault(itemDefType) : "";
    form.setValue(fieldPath as any, [...values, def] as any, {
      shouldDirty: true,
      shouldValidate: false,
    });
  };

  const removeItem = (index: number) => {
    const next = values.filter((_, i) => i !== index);
    form.setValue(fieldPath as any, next as any, {
      shouldDirty: true,
      shouldValidate: false,
    });
  };

  return (
    <AccordionItem value={name} className="border-none">
      <AccordionTrigger>{title}</AccordionTrigger>
      <AccordionContent>
        {values.map((_, index) => {
          const cellPath = `${fieldPath}.${index}`;
          return (
            <div className="mt-4 flex flex-col" key={`${fieldPath}-${index}`}>
              {itemDefType ? (
                <PrimitiveArrayRow
                  form={form}
                  itemSchema={itemDefType}
                  cellPath={cellPath}
                />
              ) : null}
              <div className="my-4 flex justify-end">
                <Button
                  variant="secondary"
                  size="icon"
                  type="button"
                  className="hover:bg-zinc-300 hover:text-black focus:ring-0 focus:ring-offset-0 focus-visible:ring-0 focus-visible:ring-offset-0 dark:bg-white dark:text-black dark:hover:bg-zinc-300 dark:hover:text-black dark:hover:ring-0 dark:hover:ring-offset-0 dark:focus-visible:ring-0 dark:focus-visible:ring-offset-0"
                  onClick={() => removeItem(index)}
                >
                  <Trash className="size-4" />
                </Button>
              </div>
              <Separator />
            </div>
          );
        })}
        <Button
          type="button"
          variant="secondary"
          onClick={appendItem}
          className="mt-4 flex items-center"
        >
          <Plus className="mr-2" size={16} />
          Add
        </Button>
      </AccordionContent>
    </AccordionItem>
  );
}

function PrimitiveArrayRow({
  form,
  itemSchema,
  cellPath,
}: {
  form: ReturnType<typeof useForm>;
  itemSchema: z.ZodType;
  cellPath: string;
}) {
  const baseSchema = getBaseSchema(itemSchema) as z.ZodType | null;
  const t = baseSchema ? getBaseType(baseSchema) : "";

  if (t === "ZodBoolean") {
    return (
      <FormField
        control={form.control as any}
        name={cellPath}
        render={({ field }) => (
          <FormItem className="flex flex-row items-center gap-2 space-y-0">
            <FormControl>
              <input
                type="checkbox"
                aria-label="Toggle"
                checked={Boolean(field.value)}
                onChange={(e) => field.onChange(e.target.checked)}
              />
            </FormControl>
            <FormLabel className="font-normal cursor-pointer">
              {(field.value as boolean | undefined) ? "Selected" : "Not selected"}
            </FormLabel>
            <FormMessage />
          </FormItem>
        )}
      />
    );
  }

  const inputType = t === "ZodNumber" ? ("number" as const) : ("text" as const);

  return (
    <FormField
      control={form.control as any}
      name={cellPath}
      render={({ field }) => (
        <FormItem className="space-y-2">
          <FormLabel className="sr-only">Row value</FormLabel>
          <FormControl>
            <Input
              type={inputType}
              name={field.name}
              ref={field.ref}
              onBlur={field.onBlur}
              value={
                field.value === undefined || field.value === null
                  ? ""
                  : String(field.value)
              }
              onChange={(ev) =>
                field.onChange(
                  inputType === "number"
                    ? Number.isNaN(ev.target.valueAsNumber)
                      ? undefined
                      : ev.target.valueAsNumber
                    : ev.target.value,
                )
              }
            />
          </FormControl>
          <FormMessage />
        </FormItem>
      )}
    />
  );
}

import { Checkbox } from "@/components/ui/checkbox";
import { FormControl, FormItem } from "@/components/ui/form";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";
import AutoFormLabel from "../common/label";

export default function AutoFormCheckbox({
  label,
  isRequired,
  field,
  fieldConfigItem,
  fieldProps,
}: AutoFormInputComponentProps) {
  return (
    <div>
      <FormItem>
        <div className="mb-3 flex items-center gap-3">
          <FormControl>
            <Checkbox
              checked={field.value}
              onCheckedChange={field.onChange}
              {...fieldProps}
            />
          </FormControl>
          <AutoFormLabel
            label={fieldConfigItem?.label || label}
            isRequired={isRequired}
          />
        </div>
      </FormItem>
      <AutoFormTooltip fieldConfigItem={fieldConfigItem} />
    </div>
  );
}

import { DatePicker } from "@/components/ui/date-picker";
import { FormControl, FormItem, FormMessage } from "@/components/ui/form";
import { z } from "zod";
import AutoFormLabel from "../common/label";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";
import { getBaseSchema, getBaseType } from "../helpers";

/**
 * Convert a value to a Date object if needed.
 * Handles both Date objects (from z.date()) and ISO strings (from z.fromJSONSchema with format: date-time)
 */
function toDate(value: unknown, dateOnly: boolean): Date | undefined {
  if (!value) return undefined;
  if (value instanceof Date) return value;
  if (typeof value === "string") {
    const date = new Date(dateOnly && /^\d{4}-\d{2}-\d{2}$/.test(value) ? `${value}T00:00:00` : value);
    return isNaN(date.getTime()) ? undefined : date;
  }
  return undefined;
}

export default function AutoFormDate({
  label,
  isRequired,
  field,
  fieldConfigItem,
  fieldProps,
  zodItem,
}: AutoFormInputComponentProps) {
  // Determine if the underlying schema expects a Date object or string
  // z.date() has base type "ZodDate", while z.fromJSONSchema with format: date-time creates a ZodString
  const baseType = getBaseType(zodItem);
  const expectsDateObject = baseType === "ZodDate";
  const baseSchema = getBaseSchema(zodItem);
  // Stored nullable JSON Schema dates reconstruct as a date-string/null union.
  const dateSchema = baseSchema instanceof z.ZodUnion && baseSchema.options.length === 2 && baseSchema.options.some((option) => option instanceof z.ZodNull)
    ? baseSchema.options.find((option) => !(option instanceof z.ZodNull))
    : baseSchema;
  const expectsDateOnly = !!dateSchema && (
    ("format" in dateSchema && dateSchema.format === "date") ||
    (dateSchema instanceof z.ZodString && !!dateSchema._zod.def.checks?.some((check) => "format" in check._zod.def && check._zod.def.format === "date"))
  );

  const handleChange = (date: Date | undefined) => {
    if (!date) {
      field.onChange(expectsDateOnly && zodItem.isNullable() ? null : undefined);
      return;
    }
    // If the schema is z.date(), pass Date object
    // If the schema is string (from JSON Schema), pass ISO string
    if (expectsDateObject) {
      field.onChange(date);
    } else if (expectsDateOnly) {
      field.onChange(`${String(date.getFullYear()).padStart(4, "0")}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`);
    } else {
      field.onChange(date.toISOString());
    }
  };

  return (
    <FormItem>
      <AutoFormLabel
        label={fieldConfigItem?.label || label}
        isRequired={isRequired}
      />
      <FormControl>
        <DatePicker
          date={toDate(field.value, expectsDateOnly)}
          setDate={handleChange}
          {...fieldProps}
        />
      </FormControl>
      <AutoFormTooltip fieldConfigItem={fieldConfigItem} />

      <FormMessage />
    </FormItem>
  );
}

import {
  FormControl,
  FormItem,
  FormMessage,
} from "@/components/ui/form";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import * as z from "zod";
import AutoFormLabel from "../common/label";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";
import { getBaseSchema } from "../helpers";

/**
 * Get enum values from a ZodEnum schema.
 * In Zod v4, enum values are accessed via the .options property or .enum property.
 */
function getEnumValues(schema: z.ZodEnum<any>): string[] {
  // Zod v4: use .options or .enum to get the array of enum values
  if (Array.isArray((schema as any).options)) {
    return (schema as any).options;
  }
  // Fallback: try the .enum property which contains {value: value} entries
  if ((schema as any).enum) {
    return Object.values((schema as any).enum);
  }
  // Last resort: check _zod.def.entries
  const def = (schema as any)._zod?.def;
  if (def?.entries) {
    return Object.values(def.entries);
  }
  return [];
}

export default function AutoFormEnum({
  label,
  isRequired,
  field,
  fieldConfigItem,
  zodItem,
  fieldProps,
}: AutoFormInputComponentProps) {
  const baseSchema = getBaseSchema(zodItem) as unknown as z.ZodEnum<any>;
  const baseValues = getEnumValues(baseSchema);

  let values: [string, string][] = [];
  if (!baseValues || baseValues.length === 0) {
    values = [];
  } else {
    values = baseValues.map((value: string) => [value, value]);
  }

  function findItem(value: any) {
    return values.find((item) => item[0] === value);
  }

  // Guard: Ignore empty value changes when a valid value is already set.
  // This prevents Radix Select from resetting the value during controlled value transitions.
  const handleValueChange = (val: string) => {
    if (val === "" && field.value && field.value !== "") {
      return; // Ignore spurious empty value callback
    }
    field.onChange(val);
  };

  return (
    <FormItem>
      <AutoFormLabel
        label={fieldConfigItem?.label || label}
        isRequired={isRequired}
      />
      <FormControl>
        <Select
          onValueChange={handleValueChange}
          value={field.value ?? ""}
          {...fieldProps}
        >
          <SelectTrigger className={fieldProps.className}>
            <SelectValue placeholder={fieldConfigItem.inputProps?.placeholder}>
              {field.value ? findItem(field.value)?.[1] : "Select an option"}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            {values.map(([value, label]) => (
              <SelectItem value={label} key={value}>
                {label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </FormControl>
      <AutoFormTooltip fieldConfigItem={fieldConfigItem} />
      <FormMessage />
    </FormItem>
  );
}

"use client";

import { createContext, useContext, useEffect, useState } from "react";
import { useFormContext } from "react-hook-form";
import { FormControl, FormItem, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import AutoFormLabel from "../common/label";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";

export const FileUploadStatusContext = createContext<(name: string, status: "uploading" | "failed" | null) => void>(() => {});

export default function AutoFormFile({ field, fieldProps, fieldConfigItem, label, isRequired }: AutoFormInputComponentProps) {
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const form = useFormContext();
  const reportStatus = useContext(FileUploadStatusContext);
  useEffect(() => () => reportStatus(field.name, null), [field.name, reportStatus]);
  const onUpload = fieldConfigItem.onUpload;
  return (
    <FormItem>
      <AutoFormLabel label={fieldConfigItem.label || label} isRequired={isRequired} />
      <FormControl>
        <Input type="file" name={field.name} onBlur={field.onBlur} accept={fieldProps.accept} disabled={fieldProps.disabled || uploading || !onUpload}
          required={isRequired && !field.value}
          onChange={async event => {
            const input = event.currentTarget;
            const file = input.files?.[0];
            if (!file || !onUpload) return;
            setUploading(true);
            reportStatus(field.name, "uploading");
            setError(null);
            form.setError(field.name, { type: "upload", message: "Upload in progress" });
            try {
              const url = await onUpload(file);
              if (typeof url !== "string" || !url.trim()) throw new Error("Upload must return a URL string");
              field.onChange(url);
              form.clearErrors(field.name);
              reportStatus(field.name, null);
            } catch (error) {
              const message = error instanceof Error ? error.message : "Upload failed";
              setError(message);
              reportStatus(field.name, "failed");
              form.setError(field.name, { type: "upload", message });
            } finally { setUploading(false); input.value = ""; }
          }} />
      </FormControl>
      <p className="text-sm text-muted-foreground" role="status">{uploading ? "Uploading…" : !onUpload ? "File uploads are not configured." : field.value ? "File uploaded" : ""}</p>
      {error && <p role="alert" className="text-sm text-destructive">{error}</p>}
      <AutoFormTooltip fieldConfigItem={fieldConfigItem} />
      <FormMessage />
    </FormItem>
  );
}

import { FormControl, FormItem, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import AutoFormLabel from "../common/label";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";

export default function AutoFormInput({
  label,
  isRequired,
  fieldConfigItem,
  fieldProps,
}: AutoFormInputComponentProps) {
  const { showLabel: _showLabel, ...fieldPropsWithoutShowLabel } = fieldProps;
  const showLabel = _showLabel === undefined ? true : _showLabel;
  const type = fieldProps.type || "text";

  return (
    <div className="flex flex-row  items-center space-x-2">
      <FormItem className="flex w-full flex-col justify-start">
        {showLabel && (
          <AutoFormLabel
            label={fieldConfigItem?.label || label}
            isRequired={isRequired}
          />
        )}
        <FormControl>
          <Input type={type} {...fieldPropsWithoutShowLabel} />
        </FormControl>
        <AutoFormTooltip fieldConfigItem={fieldConfigItem} />
        <FormMessage />
      </FormItem>
    </div>
  );
}

import { FormControl, FormItem, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import AutoFormLabel from "../common/label";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";

