import { matchesShowIf } from "@/lib/form-visibility";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { FormField } from "@/components/ui/form";
import { useForm, useFormContext } from "react-hook-form";
import * as z from "zod";
import { DEFAULT_ZOD_HANDLERS, INPUT_COMPONENTS } from "../config";
import type { Dependency, FieldConfig, FieldConfigItem } from "../types";
import {
  beautifyObjectName,
  getBaseSchema,
  getBaseType,
  sortFieldsByOrder,
  zodToHtmlInputProps,
} from "../helpers";
import AutoFormArray from "./array";
import resolveDependencies from "../dependencies";

function DefaultParent({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

export default function AutoFormObject<
  SchemaType extends z.ZodObject<any, any>,
>({
  schema,
  form,
  fieldConfig,
  path = [],
  dependencies = [],
}: {
  schema: SchemaType | z.ZodType<z.infer<SchemaType>>;
  form: ReturnType<typeof useForm>;
  fieldConfig?: FieldConfig<z.infer<SchemaType>>;
  path?: string[];
  dependencies?: Dependency<z.infer<SchemaType>>[];
}) {
  const { watch } = useFormContext(); // Use useFormContext to access the watch function

  if (!schema) {
    return null;
  }
  const { shape } = getBaseSchema<SchemaType>(schema as SchemaType) || {};

  if (!shape) {
    return null;
  }

  const handleIfZodNumber = (item: z.ZodType) => {
    // Check for ZodNumber (Zod v4 uses type in _zod.def)
    const def = (item as any)._zod?.def;
    const defType = def?.type;
    const innerDefType = def?.innerType?._zod?.def?.type;

    const isZodNumber =
      defType === "number" || defType === "int" || defType === "float";
    const isInnerZodNumber =
      innerDefType === "number" ||
      innerDefType === "int" ||
      innerDefType === "float";

    if (isZodNumber && def) {
      def.coerce = true;
    } else if (isInnerZodNumber && def?.innerType?._zod?.def) {
      def.innerType._zod.def.coerce = true;
    }

    return item;
  };

  const sortedFieldKeys = sortFieldsByOrder(fieldConfig, Object.keys(shape));

  return (
    <Accordion type="multiple" className="space-y-5 border-none">
      {sortedFieldKeys.map((name) => {
        let item = shape[name] as z.ZodType;
        item = handleIfZodNumber(item);
        const zodBaseType = getBaseType(item);
        const itemName = beautifyObjectName(name);
        const key = [...path, name].join(".");

        const {
          isHidden,
          isDisabled,
          isRequired: isRequiredByDependency,
          overrideOptions,
        } = resolveDependencies(dependencies, name, watch);
        const siblingValues = path.length ? watch(path.join(".")) ?? {} : watch();
        if (isHidden || !matchesShowIf(fieldConfig?.[name]?.showIf, siblingValues)) {
          return null;
        }

        if (zodBaseType === "ZodObject") {
          // Check if there's a custom fieldType for this object field
          // This allows relation fields (belongsTo) and other custom handlers to override default object behavior
          const objectFieldConfig: FieldConfigItem = fieldConfig?.[name] ?? {};
          if (typeof objectFieldConfig.fieldType === "function") {
            // Custom component for this object field - render it like a regular field
            const zodInputProps = zodToHtmlInputProps(item);
            // Determine required status (same logic as regular fields)
            let isRequired =
              isRequiredByDependency || zodInputProps.required || false;
            if (objectFieldConfig.inputProps?.required !== undefined) {
              isRequired = objectFieldConfig.inputProps.required;
            }
            const CustomComponent = objectFieldConfig.fieldType;
            const ParentElement =
              objectFieldConfig.renderParent ?? DefaultParent;
            return (
              <FormField
                control={form.control as any}
                name={key}
                key={key}
                render={({ field }) => {
                  const fieldProps = {
                    ...zodInputProps,
                    ...field,
                    ...objectFieldConfig.inputProps,
                    disabled:
                      objectFieldConfig.inputProps?.disabled || isDisabled,
                    ref: undefined,
                    value: field.value,
                  };
                  return (
                    <ParentElement key={`${key}.parent`}>
                      <CustomComponent
                        zodInputProps={zodInputProps}
                        field={field}
                        fieldConfigItem={objectFieldConfig}
                        label={objectFieldConfig.label || itemName}
                        isRequired={isRequired}
                        zodItem={item}
                        fieldProps={fieldProps}
                      />
                    </ParentElement>
                  );
                }}
              />
            );
          }

          return (
            <AccordionItem value={name} key={key} className="border-none">
              <AccordionTrigger>{itemName}</AccordionTrigger>
              <AccordionContent className="p-2">
                <AutoFormObject
                  schema={item as unknown as z.ZodObject<any, any>}
                  form={form}
                  fieldConfig={(fieldConfig?.[name] ?? {}) as any}
                  path={[...path, name]}
                />
              </AccordionContent>
            </AccordionItem>
          );
        }
        if (zodBaseType === "ZodArray") {
          // Check if there's a custom fieldType for this array field
          // This allows relation fields and other custom array handlers to override default array behavior
          const arrayFieldConfig: FieldConfigItem = fieldConfig?.[name] ?? {};
          if (typeof arrayFieldConfig.fieldType === "function") {
            // Custom component for this array field - render it like a regular field
            const zodInputProps = zodToHtmlInputProps(item);
            // Determine required status (same logic as regular fields)
            let isRequired =
              isRequiredByDependency || zodInputProps.required || false;
            if (arrayFieldConfig.inputProps?.required !== undefined) {
              isRequired = arrayFieldConfig.inputProps.required;
            }
            const CustomComponent = arrayFieldConfig.fieldType;
            const ParentElement = arrayFieldConfig.renderParent ?? DefaultParent;
            return (
              <FormField
                control={form.control as any}
                name={key}
                key={key}
                render={({ field }) => {
                  const fieldProps = {
                    ...zodInputProps,
                    ...field,
                    ...arrayFieldConfig.inputProps,
                    disabled:
                      arrayFieldConfig.inputProps?.disabled || isDisabled,
                    ref: undefined,
                    value: field.value,
                  };
                  return (
                    <ParentElement key={`${key}.parent`}>
                      <CustomComponent
                        zodInputProps={zodInputProps}
                        field={field}
                        fieldConfigItem={arrayFieldConfig}
                        label={arrayFieldConfig.label || itemName}
                        isRequired={isRequired}
                        zodItem={item}
                        fieldProps={fieldProps}
                      />
                    </ParentElement>
                  );
                }}
              />
            );
          }

          return (
            <AutoFormArray
              key={key}
              name={name}
              item={item as unknown as z.ZodArray<any>}
              form={form}
              fieldConfig={arrayFieldConfig}
              path={[...path, name]}
            />
          );
        }

        const fieldConfigItem: FieldConfigItem = fieldConfig?.[name] ?? {};
        const zodInputProps = zodToHtmlInputProps(item);

        // Determine required status:
        // 1. If dependency sets required, use that
        // 2. If fieldConfig explicitly sets required (true/false), use that
        // 3. Otherwise, use zodInputProps.required
        let isRequired = isRequiredByDependency || zodInputProps.required || false;
        if (fieldConfigItem.inputProps?.required !== undefined) {
          isRequired = fieldConfigItem.inputProps.required;
        }

        if (overrideOptions) {
          item = z.enum(overrideOptions) as unknown as z.ZodType;
        }

        return (
          <FormField
            control={form.control as any}
            name={key}
            key={key}
            render={({ field }) => {
              const inputType =
                fieldConfigItem.fieldType ??
                DEFAULT_ZOD_HANDLERS[zodBaseType] ??
                "fallback";

              const InputComponent =
                typeof inputType === "function"
                  ? inputType
                  : INPUT_COMPONENTS[inputType];

              const ParentElement =
                fieldConfigItem.renderParent ?? DefaultParent;

              const defaultValue = fieldConfigItem.inputProps?.defaultValue;
              const value = field.value ?? defaultValue ?? "";

              // Destructure defaultValue out of inputProps so it isn't spread
              // alongside value — having both makes React warn about a mixed
              // controlled/uncontrolled input.
              const { defaultValue: _omitDV, ...safeInputProps } =
                (fieldConfigItem.inputProps ?? {}) as Record<string, unknown>;
              const fieldProps = {
                ...zodToHtmlInputProps(item),
                ...field,
                onChange: zodBaseType === "ZodNumber" && inputType === "number"
                  ? (event: React.ChangeEvent<HTMLInputElement>) => field.onChange(Number(event.target.value))
                  : field.onChange,
                ...safeInputProps,
                disabled: (safeInputProps.disabled as boolean | undefined) || isDisabled,
                ref: undefined,
                value: value,
              };

              if (InputComponent === undefined) {
                return <></>;
              }

              return (
                <ParentElement key={`${key}.parent`}>
                  <InputComponent
                    zodInputProps={zodInputProps}
                    field={field}
                    fieldConfigItem={fieldConfigItem}
                    label={itemName}
                    isRequired={isRequired}
                    zodItem={item}
                    fieldProps={fieldProps}
                    className={fieldProps.className}
                  />
                </ParentElement>
              );
            }}
          />
        );
      })}
    </Accordion>
  );
}

import {
  FormControl,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import * as z from "zod";
import AutoFormLabel from "../common/label";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";
import { getBaseSchema } from "../helpers";

/**
 * Get enum values from a ZodEnum schema.
 * In Zod v4, enum values are accessed via the .options property or .enum property.
 */
function getEnumValues(schema: z.ZodEnum<any>): string[] {
  // Zod v4: use .options or .enum to get the array of enum values
  if (Array.isArray((schema as any).options)) {
    return (schema as any).options;
  }
  // Fallback: try the .enum property which contains {value: value} entries
  if ((schema as any).enum) {
    return Object.values((schema as any).enum);
  }
  // Last resort: check _zod.def.entries
  const def = (schema as any)._zod?.def;
  if (def?.entries) {
    return Object.values(def.entries);
  }
  return [];
}

export default function AutoFormRadioGroup({
  label,
  isRequired,
  field,
  zodItem,
  fieldProps,
  fieldConfigItem,
}: AutoFormInputComponentProps) {
  const baseSchema = getBaseSchema(zodItem) as unknown as z.ZodEnum<any>;
  const values = getEnumValues(baseSchema);

  return (
    <div>
      <FormItem>
        <AutoFormLabel
          label={fieldConfigItem?.label || label}
          isRequired={isRequired}
        />
        <FormControl>
          <RadioGroup
            onValueChange={field.onChange}
            defaultValue={field.value}
            {...fieldProps}
          >
            {values?.map((value: string) => (
              <FormItem
                key={value}
                className="mb-2 flex items-center gap-3 space-y-0"
              >
                <FormControl>
                  <RadioGroupItem value={value} />
                </FormControl>
                <FormLabel className="font-normal">{value}</FormLabel>
              </FormItem>
            ))}
          </RadioGroup>
        </FormControl>
        <FormMessage />
      </FormItem>
      <AutoFormTooltip fieldConfigItem={fieldConfigItem} />
    </div>
  );
}

import { FormControl, FormItem } from "@/components/ui/form";
import { Switch } from "@/components/ui/switch";
import AutoFormLabel from "../common/label";
import AutoFormTooltip from "../common/tooltip";
import type { AutoFormInputComponentProps } from "../types";

export default function AutoFormSwitch({
  label,
  isRequired,
  field,
  fieldConfigItem,
  fieldProps,
}: AutoFormInputComponentProps) {
  return (
    <div>
      <FormItem>
        <div className="flex items-center gap-3">
          <FormControl>
            <Switch
              checked={field.value}
              onCheckedChange={field.onChange}
              {...fieldProps}
            />
          </FormControl>
          <AutoFormLabel
            label={fieldConfigItem?.label || label}
            isRequired={isRequired}
          />
        </div>
      </FormItem>
      <AutoFormTooltip fieldConfigItem={fieldConfigItem} />
